<?php
require_once 'conexion.php';
$buscar=trim($_GET['buscar']??''); $porPagina=10; $paginaSolicitada=filter_var($_GET['pagina']??1,FILTER_VALIDATE_INT); if(!$paginaSolicitada||$paginaSolicitada<1)$paginaSolicitada=1;
$sql=' FROM dbo.medicamento m INNER JOIN dbo.categoria c ON c.id_categoria=m.id_categoria'; $params=[];
if($buscar!==''){ $sql.=' WHERE m.nombre LIKE ? OR m.codigo_barras LIKE ? OR c.nombre LIKE ? OR m.concentracion LIKE ?'; $q='%'.$buscar.'%'; $params=[$q,$q,$q,$q]; }
$stmt=$pdo->prepare('SELECT COUNT(*)'.$sql);$stmt->execute($params);$total=(int)$stmt->fetchColumn();$paginas=max(1,(int)ceil($total/$porPagina));$pagina=min($paginas,$paginaSolicitada);$offset=($pagina-1)*$porPagina;
$stmt=$pdo->prepare('SELECT m.id_medicamento,m.nombre,m.presentacion,m.concentracion,m.precio_venta,m.precio_costo,m.iva_porcentaje,m.requiere_receta,m.codigo_barras,c.nombre AS categoria'.$sql.' ORDER BY m.nombre OFFSET ? ROWS FETCH NEXT ? ROWS ONLY');$i=1;foreach($params as $p)$stmt->bindValue($i++,$p,PDO::PARAM_STR);$stmt->bindValue($i++,$offset,PDO::PARAM_INT);$stmt->bindValue($i,$porPagina,PDO::PARAM_INT);$stmt->execute();$medicamentos=$stmt->fetchAll();
function h($v){return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
?>
<input type="hidden" id="pagina-productos" name="pagina" value="<?=$pagina?>"><div class="table-container"><table class="table is-fullwidth is-striped is-hoverable"><thead><tr><th>ID</th><th>Medicamento</th><th>Categoría</th><th>Presentación</th><th>Concentración</th><th>Precio venta</th><th>IVA %</th><th>Receta</th><th>Acciones</th></tr></thead><tbody>
<?php if(!$medicamentos):?><tr><td colspan="9" class="has-text-centered">No hay medicamentos registrados.</td></tr><?php endif;?>
<?php foreach($medicamentos as $m):?><tr><td><?=(int)$m['id_medicamento']?></td><td><strong><?=h($m['nombre'])?></strong><br><small><?=h($m['codigo_barras']?:'Sin código de barras')?></small></td><td><?=h($m['categoria'])?></td><td><?=h($m['presentacion'])?></td><td><?=h($m['concentracion'])?></td><td>₡<?=number_format((float)$m['precio_venta'],2,',','.')?></td><td><?=number_format((float)$m['iva_porcentaje'],2)?></td><td><?=$m['requiere_receta']?'Sí':'No'?></td><td><div class="buttons are-small"><button class="button is-info" hx-get="producto_form.php?id=<?=(int)$m['id_medicamento']?>" hx-target="#modal-contenido">Editar</button><button class="button is-danger" hx-delete="producto_eliminar.php?id=<?=(int)$m['id_medicamento']?>" hx-target="#mensaje-lista" hx-confirm="¿Eliminar este medicamento? Si tiene ventas, compras o lotes asociados, SQL Server impedirá eliminarlo.">Eliminar</button></div></td></tr><?php endforeach;?></tbody></table></div>
<div class="paginacion-productos"><p>Mostrando <?=$total?$offset+1:0?>–<?=min($offset+$porPagina,$total)?> de <?=$total?> medicamentos</p><nav class="pagination" aria-label="Páginas" hx-target="#lista-productos" hx-include="[name=buscar]" hx-swap="innerHTML"><button class="pagination-previous" hx-get="productos_lista.php?pagina=<?=max(1,$pagina-1)?>" <?=$pagina===1?'disabled':''?>>Anterior</button><button class="pagination-next" hx-get="productos_lista.php?pagina=<?=min($paginas,$pagina+1)?>" <?=$pagina===$paginas?'disabled':''?>>Siguiente</button><ul class="pagination-list"><li><span class="pagination-link is-current"><?=$pagina?> / <?=$paginas?></span></li></ul></nav></div>
